	@Test
	void measuredPlanningRejectsBudgetExhaustion() throws Exception {
		String modeProperty = "rdf4j.optimizer.lmdb.cascades.mode";
		String budgetProperty = "rdf4j.optimizer.lmdb.cascades.budget";
		String timeoutProperty = "rdf4j.optimizer.lmdb.cascades.timeoutMillis";
		String previousMode = System.getProperty(modeProperty);
		String previousBudget = System.getProperty(budgetProperty);
		String previousTimeout = System.getProperty(timeoutProperty);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(false)
				.setSketchEstimatorEnabled(false)
				.setBackgroundRawSamplingEnabled(false);
		LmdbStore store = new LmdbStore(tempDir.resolve("budget-receipt").toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				StringBuilder query = new StringBuilder("SELECT * WHERE { ");
				for (int index = 0; index < 6; index++) {
					connection.add(values.createIRI("urn:node:" + index), values.createIRI("urn:p" + index),
							values.createIRI("urn:node:" + (index + 1)));
					query.append("?s")
							.append(index)
							.append(" <urn:p")
							.append(index)
							.append("> ?s")
							.append(index + 1)
							.append(" . ");
				}
				query.append('}');
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
				BudgetObservedPlanningState state = new BudgetObservedPlanningState();
				state.store = store;
				state.connection = connection;
				state.query = query.toString();
				System.setProperty(modeProperty, "budgeted");
				System.setProperty(budgetProperty, "1");
				System.setProperty(timeoutProperty, "60000");
				IllegalStateException failure;
				try {
					failure = assertThrows(IllegalStateException.class,
							() -> new ThemeQueryPlanRunBenchmark().planQuery(state),
							"a budget-exhausted plan must not become a benchmark measurement");
				} finally {
					assertEquals(1, state.preparations, "the measured call must prepare exactly one plan");
					assertEquals("BUDGET_EXHAUSTED", state.completeness,
							"the measured invocation itself must exhaust the planning budget");
				}
				assertTrue(failure.getMessage().contains("BUDGET_EXHAUSTED"), failure::getMessage);
				assertNotNull(state.dataset);
				var closedSource = new SailDatasetTripleTermSource(store.getValueFactory(), state.dataset);
				assertThrows(IllegalStateException.class,
						() -> SailDatasetReadComposition.resolve(closedSource, SailDataset.class,
								(left, right) -> Optional.empty()),
						"rejected benchmark preparation must release its dataset");
				state.planningExpectation = PlanningExpectation.BUDGET_EXHAUSTED;
				assertTrue(new ThemeQueryPlanRunBenchmark().planQuery(state) > 0,
						"an explicitly expected bounded plan remains measurable");
				assertEquals(2, state.preparations);
				assertEquals("BUDGET_EXHAUSTED", state.completeness);
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				restoreProperty(modeProperty, previousMode);
				restoreProperty(budgetProperty, previousBudget);
				restoreProperty(timeoutProperty, previousTimeout);
			}
		}
	}

	private static final class BudgetObservedPlanningState extends ThemeQueryPlanRunBenchmark.PlanningState {
		private int preparations;
		private String completeness;
		private SailDataset dataset;

		@Override
		protected LmdbBenchmarkQueryPlan preparePlan(boolean captureOptimizedPlan) {
			LmdbBenchmarkQueryPlan plan = super.preparePlan(true);
			try {
				preparations++;
				plan.inspectCapturedOptimizedExpression(
						expression -> completeness = expression
								.getStringMetricPlanned("optimizer.cascadesCompleteness"));
				plan.inspectCapturedDataset(captured -> dataset = captured);
				return plan;
			} catch (RuntimeException | Error failure) {
				try {
					plan.close();
				} catch (RuntimeException | Error cleanup) {
					if (cleanup != failure) {
						failure.addSuppressed(cleanup);
					}
				}
				throw failure;
			}
		}
	}

	private static void restoreProperty(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}

